    Producer(Rig& r,std::vector<f::Channel> c):rig(r),channels(std::move(c)),fields(r.device.p,r.fence.p,channels),pool(r.device.p,emitter(),8){std::string error;rig.begin();require(pool.initialize(rig.commands.p,rig.ticket(),error)&&pool.step(rig.commands.p,rig.ticket(),0,8,0,41,{},error),error.c_str());rig.submit();}
