        std::string error;if(!handles.count(source)){f::LocalSpec s;s.owner="smoke";s.source=source;s.originFine={-1,-1,-1};s.dimensions={3,3,3};s.finePerWorld=1;for(unsigned i=0;i<channels.size();++i)if(channels[i].domain==f::Domain::VisualReference)s.channels.push_back({i,channels[i].merge==f::Merge::Sum?f::ProjectionReduction::VolumeAverage:f::ProjectionReduction::Maximum});f::GpuLocalHandle h;require(fields.create(s,h,error),error.c_str());handles[source]=h;}
        const auto h=handles.at(source);rig.begin();require(fields.begin(h,rig.commands.p,rig.ticket(),tick,error),error.c_str());for(unsigned i=0;i<channels.size();++i)if(channels[i].domain==f::Domain::VisualReference)require(fields.splat(h,i,pool,i==0?density:maximum,rig.commands.p,rig.ticket(),error),error.c_str());require(fields.resolve(h,rig.commands.p,rig.ticket(),error),error.c_str());auto result=fields.project(h,publishTick==UINT64_MAX?tick:publishTick,rig.commands.p,rig.ticket(),error);require(!!result,error.c_str());rig.submit();return result;
