    require(gpu.publish(wa,a,1,1,error)==f::PublishResult::Duplicate,"Committed duplicate rejected");auto updated=producer.make(1,2,25,5);require(gpu.publish(wa,updated,2,2,error)==f::PublishResult::Accepted,error.c_str());referencePublish(cpu,ca,updated,2,2,25,5);require(gpu.sourceView("smoke",1).epoch==1,"Source epoch changed before barrier");commit(rig,gpu,cpu,2);auto current=gpu.view(reader,error);compare(cpu,cr,samples,query.run(rig,current,samples,2),2);const auto retained=query.run(rig,old,samples,1);require(retained.size()==original.size()&&std::memcmp(retained.data(),original.data(),retained.size()*sizeof(f::GpuFieldAnswer))==0,"New commit mutated older WF snapshot");require(gpu.publish(wa,a,1,3,error)==f::PublishResult::OldEpoch&&gpu.publish(wa,a,3,3,error)==f::PublishResult::PastTick,"Epoch/data-time regression accepted");require(gpu.publish(wa,updated,2,3,error)==f::PublishResult::Conflict,"Same epoch conflicting time accepted");
    require(gpu.withdraw(wb,2,2,3,error)==f::PublishResult::Accepted,error.c_str());referenceWithdraw(cpu,cb,b,2,3);commit(rig,gpu,cpu,3);auto remaining=gpu.view(reader,error);auto result=query.run(rig,remaining,{{0,0,0,0},{0,0,0,1}},3);compare(cpu,cr,{{0,0,0,0},{0,0,0,1}},result,3);require(result[0].value==200&&result[0].clamped==0,"Withdrawal subtracted a saturated total");require(!gpu.sourceView("smoke",2).hasContribution&&gpu.sourceView("smoke",2).epoch==2,"Withdrawal tombstone not committed");require(gpu.withdraw(wb,2,2,3,error)==f::PublishResult::Duplicate,"Withdrawal resend not idempotent");
