    evidence.push_back({{"case","replace-withdraw-query"},{"comparisons",comparisons},{"residentBrickPayloads",gpu.stats().residentPages},{"ownAccountedBytes",gpu.stats().accountedBytes}});old.reset();current.reset();remaining.reset();absent.reset();require(gpu.release(wb,error)&&gpu.release(reader,error)&&cpu.release(cb)&&cpu.release(cr),"Lease cleanup failed");gpu.collect();require(gpu.stats().accountedBytes==0&&gpu.stats().sources==0&&gpu.shutdown(error),error.c_str());a.reset();b.reset();updated.reset();producer.close();++groups;
