    require(gpu.withdraw(w2,2,2,1,error)==f::PublishResult::Accepted&&gpu.withdraw(w3,3,2,1,error)==f::PublishResult::Accepted,error.c_str());referenceWithdraw(cpu,c2,b,2,1);referenceWithdraw(cpu,c3,d,2,1);commit(rig,gpu,cpu,1);auto exact=gpu.view(reader,error);result=query.run(rig,exact,{{0,0,0,0}},1);compare(cpu,cr,{{0,0,0,0}},result,1);require(result[0].value==INT32_MAX&&result[0].clamped==0,"Rebuilt source retained a stale saturation bit");
