    f::GpuLocalGrid shifted;shifted.worldCellMetres=.5f;f::GpuVisualWorld grid(rig.device.p,rig.fence.p,c,{},shifted);auto gridWriter=acquire(grid,request(true));require(grid.publish(gridWriter,a,1,sourceTick+9,error)==f::PublishResult::AccessDenied,"Mismatched metre grid accepted");require(grid.release(gridWriter,error)&&grid.shutdown(error),error.c_str());
    view.reset();stale.reset();for(auto h:{writer,otherWriter,reader,staleLease})require(gpu.release(h,error),error.c_str());gpu.collect();require(gpu.shutdown(error),error.c_str());a.reset();producer.close();++groups;
