    f::GpuFieldTransaction cleanup(world,{&a,&b,&outsider});require(cleanup.begin(error)&&a.retire(ah,2).accepted()&&b.retire(bh,2).accepted()&&outsider.retire(oh,2).accepted()&&outsider.retire(local,2).accepted(),"Cannot explicitly enlist former outsider");rig.begin();require(cleanup.commit(rig.commands.p,rig.ticket(),2,error).accepted(),error.c_str());rig.submit();require(a.settle(ah).accepted()&&b.settle(bh).accepted()&&outsider.settle(oh).accepted(),"Enlisted retirement failed acknowledgment");
    require(world.release(writer,error)&&!group.begin(error),"Group adopted an uncommitted raw source removal");commit(rig,world,3);require(group.begin(error),"Committed source removal still blocked clean group");group.rollback();require(world.release(reader,error)&&world.shutdown(error),error.c_str());p1.reset();p2.reset();p3.reset();p4.reset();p5.reset();producer.close();
    evidence.push_back({{"case","joint-publication-ownership"},{"preexistingStagingRejected",true},{"unacknowledgedParticipantRejected",true},{"unenlistedControllerRejected",true},{"rawWriterMutationRejected",true},{"teardownCancelsJointScope",true},{"oldSnapshotPreserved",true}});++groups;
